import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void conv2d_cute_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bs,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Hout, int Wout,
    int OH_TILE, int OW_TILE, int IH_TILE, int IW_TILE, int COUT_TILE)
{
  const int n  = blockIdx.z;
  const int th = blockIdx.y; // tile row idx
  const int tw = blockIdx.x; // tile col idx
  const int oh0 = th * OH_TILE;
  const int ow0 = tw * OW_TILE;
  const int ih0 = oh0 * stride - padding;
  const int iw0 = ow0 * stride - padding;
  extern __shared__ float smem[];
  // Shared-memory tensors for a CHUNK of the weight tensor: (COUT_TILE, Cin, K, K).
  // The full weight tensor (Cout, Cin, K, K) does not, in general, fit in
  // shared memory (its size grows with Cout), so instead of staging all of
  // it at once we stage COUT_TILE output channels at a time, reusing each
  // chunk across every output position in the tile before moving on.
  // Two buffers are used (double buffering) so that the weight chunk for
  // the NEXT iteration can be loaded from global memory while the CURRENT
  // chunk is still being used for compute, overlapping load latency with
  // useful math instead of stalling at a barrier every iteration.
  const int64_t w_chunk_elems = (int64_t)COUT_TILE * Cin * K * K;
  float* sW0_ptr = smem;
  float* sW1_ptr = smem + w_chunk_elems;
  auto sW0 = make_tensor(make_smem_ptr(sW0_ptr),
                         make_shape(COUT_TILE, Cin, K, K),
                         make_stride((int64_t)Cin * K * K, (int64_t)K * K, (int64_t)K, (int64_t)1));
  auto sW1 = make_tensor(make_smem_ptr(sW1_ptr),
                         make_shape(COUT_TILE, Cin, K, K),
                         make_stride((int64_t)Cin * K * K, (int64_t)K * K, (int64_t)K, (int64_t)1));
  // Shared-memory tensor: (Cin, IH_TILE, IW_TILE), placed right after the two weight-chunk buffers.
  float* sX_ptr = smem + 2 * w_chunk_elems;
  auto sX = make_tensor(make_smem_ptr(sX_ptr),
                         make_shape(Cin, IH_TILE, IW_TILE),
                         make_stride(IH_TILE * IW_TILE, IW_TILE, 1));
  // Global input tensor for this batch element: (Cin, H, Win)
  int64_t sXn = (int64_t)Cin * H * Win;
  int64_t sXc = (int64_t)H * Win;
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(Cin, H, Win),
                         make_stride(sXc, (int64_t)Win, (int64_t)1));
  // Weight tensor: (Cout, Cin, K, K)
  auto mW = make_tensor(make_gmem_ptr(Wt),
                         make_shape(Cout, Cin, K, K),
                         make_stride((int64_t)Cin * K * K, (int64_t)K * K, (int64_t)K, (int64_t)1));
  // Global output tensor for this batch element: (Cout, Hout, Wout)
  int64_t sYn = (int64_t)Cout * Hout * Wout;
  int64_t sYc = (int64_t)Hout * Wout;
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(Cout, Hout, Wout),
                         make_stride(sYc, (int64_t)Wout, (int64_t)1));
  const int tid       = threadIdx.y * blockDim.x + threadIdx.x;
  const int nthreads   = blockDim.x * blockDim.y;
  const int kk_plane      = K * K;
  const int c_plane_chunk = Cin * kk_plane;
  const int total_w_chunk = COUT_TILE * Cin * K * K;
  const int COT = 4; // register-blocking factor: compute COT output channels per iteration,
                     // reusing each shared-memory input value across all of them.
  auto load_chunk = [&](auto& sWbuf, int cbase, int csize) {
    for (int idx = tid; idx < total_w_chunk; idx += nthreads) {
      int cot_local = idx / c_plane_chunk;
      int rem       = idx - cot_local * c_plane_chunk;
      int c         = rem / kk_plane;
      int rem2      = rem - c * kk_plane;
      int kh        = rem2 / K;
      int kw        = rem2 - kh * K;
      if (cot_local < csize) {
        int cot_global = cbase + cot_local;
        sWbuf(cot_local, c, kh, kw) = mW(cot_global, c, kh, kw);
      }
    }
  };
  // Cooperative load of the input tile into shared memory (zero-padded),
  // interleaved (without an intervening barrier) with the load of the
  // first weight chunk. Both loads are independent of one another, so
  // issuing them back-to-back lets their global-memory load latencies
  // overlap instead of being serialized behind two separate
  // __syncthreads() calls.
  const int total_elem = Cin * IH_TILE * IW_TILE;
  const int plane      = IH_TILE * IW_TILE;
  for (int idx = tid; idx < total_elem; idx += nthreads) {
    int c   = idx / plane;
    int rem = idx - c * plane;
    int ihl = rem / IW_TILE;
    int iwl = rem - ihl * IW_TILE;
    int ih = ih0 + ihl;
    int iw = iw0 + iwl;
    float v = 0.0f;
    if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
      v = mX(c, ih, iw);
    }
    sX(c, ihl, iwl) = v;
  }
  const int chunk_size0 = (Cout < COUT_TILE) ? Cout : COUT_TILE;
  load_chunk(sW0, 0, chunk_size0);
  __syncthreads();
  const int sp  = threadIdx.x; // spatial position index within the tile
  const int cg  = threadIdx.y; // channel-group index
  const int ncg = blockDim.y;
  bool valid_pixel = false;
  int ohl = 0, owl = 0, oh = 0, ow = 0;
  if (sp < OH_TILE * OW_TILE) {
    ohl = sp / OW_TILE;
    owl = sp % OW_TILE;
    oh  = oh0 + ohl;
    ow  = ow0 + owl;
    valid_pixel = (oh < Hout && ow < Wout);
  }
  auto compute_chunk = [&](auto& sWbuf, int cbase, int csize) {
    if (!valid_pixel) return;
    for (int co = cg; co < csize; co += ncg * COT) {
      float acc[COT];
      #pragma unroll
      for (int t = 0; t < COT; ++t) {
        int cot_local = co + t * ncg;
        acc[t] = (cot_local < csize && Bs != nullptr) ? Bs[cbase + cot_local] : 0.0f;
      }
      #pragma unroll
      for (int c = 0; c < Cin; ++c) {
        for (int kh = 0; kh < K; ++kh) {
          int ihl = ohl * stride + kh;
          for (int kw = 0; kw < K; ++kw) {
            int iwl = owl * stride + kw;
            float xv = sX(c, ihl, iwl);
            #pragma unroll
            for (int t = 0; t < COT; ++t) {
              int cot_local = co + t * ncg;
              if (cot_local < csize) {
                acc[t] += xv * sWbuf(cot_local, c, kh, kw);
              }
            }
          }
        }
      }
      #pragma unroll
      for (int t = 0; t < COT; ++t) {
        int cot_local = co + t * ncg;
        if (cot_local < csize) {
          mY(cbase + cot_local, oh, ow) = acc[t];
        }
      }
    }
  };
  int cout_base = 0;
  int cur = 0; // 0 -> sW0 holds the current chunk, 1 -> sW1 holds the current chunk
  while (cout_base < Cout) {
    const int chunk_size = (Cout - cout_base < COUT_TILE) ? (Cout - cout_base) : COUT_TILE;
    const int next_cout_base = cout_base + COUT_TILE;
    if (next_cout_base < Cout) {
      const int next_chunk_size = (Cout - next_cout_base < COUT_TILE) ? (Cout - next_cout_base) : COUT_TILE;
      if (cur == 0) load_chunk(sW1, next_cout_base, next_chunk_size);
      else          load_chunk(sW0, next_cout_base, next_chunk_size);
    }
    if (cur == 0) compute_chunk(sW0, cout_base, chunk_size);
    else          compute_chunk(sW1, cout_base, chunk_size);
    __syncthreads(); // ensure the next chunk's load is visible and this chunk's reads finish before its buffer is reused
    cout_base = next_cout_base;
    cur ^= 1;
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N,C,H,W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout,Cin,K,K]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int N    = (int)x_c.size(0);
  int Cin  = (int)x_c.size(1);
  int H    = (int)x_c.size(2);
  int Win  = (int)x_c.size(3);

  int Cout = (int)w_c.size(0);
  int K    = (int)w_c.size(2);
  TORCH_CHECK((int)w_c.size(1) == Cin, "w.size(1) must equal Cin");
  TORCH_CHECK((int)w_c.size(3) == K,   "kernel must be square");

  TORCH_CHECK(stride > 0 && padding >= 0, "invalid stride/padding");

  int Hout = (H + 2 * padding - K) / stride + 1;
  int Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "invalid output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && (int)b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  const int OH_TILE = 4;
  const int OW_TILE = 8; // further halved: shrinks the sX input-tile shared-memory footprint substantially so more CTAs can be resident per SM, directly targeting the profiler-flagged shared-memory-limited theoretical occupancy (25%)
  const int OC_GROUPS = 2;

  int IH_TILE = (OH_TILE - 1) * stride + K;
  int IW_TILE = (OW_TILE - 1) * stride + K;

  dim3 block(OH_TILE * OW_TILE, OC_GROUPS);
  dim3 grid((Wout + OW_TILE - 1) / OW_TILE,
            (Hout + OH_TILE - 1) / OH_TILE,
            N);

  int device = 0;
  cudaGetDevice(&device);
  int max_smem_optin = 0;
  cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
  if (max_smem_optin <= 0) {
    max_smem_optin = 48 * 1024;
  }
  size_t sX_bytes       = (size_t)Cin * IH_TILE * IW_TILE * sizeof(float);
  size_t per_cout_bytes = (size_t)Cin * K * K * sizeof(float);
  // Leave a small margin below the device's opt-in max so the launch stays
  // legal even after accounting for driver bookkeeping overhead. Additionally,
  // cap the per-block shared-memory budget at a modest fixed target instead of
  // greedily consuming the device's full opt-in maximum. The previous policy
  // maximized COUT_TILE to fill nearly all available shared memory, which
  // pinned occupancy to essentially a single resident block per SM (profiled
  // at ~16.7% theoretical occupancy, explicitly flagged by the profiler as
  // shared-memory limited). Capping the budget keeps per-block shared memory
  // small enough that multiple blocks can be resident on an SM concurrently,
  // trading a somewhat smaller weight-chunk reuse factor for substantially
  // higher occupancy and better latency hiding.
  const size_t kOccupancyFriendlySmemCap = 24576; // 24 KB per block (reduced further, in tandem with the smaller OW_TILE, to shrink per-CTA shared-memory usage and increase the number of concurrently resident CTAs per SM, improving occupancy beyond the previous ~25%)
  size_t smem_budget = ((size_t)max_smem_optin > (4 * 1024))
                            ? (size_t)max_smem_optin - (4 * 1024)
                            : (size_t)max_smem_optin;
  if (smem_budget > kOccupancyFriendlySmemCap) {
    smem_budget = kOccupancyFriendlySmemCap;
  }
  // Weight chunks are double-buffered (two copies of size COUT_TILE) so
  // that loading the NEXT chunk from global memory can be overlapped with
  // compute on the CURRENT chunk instead of stalling at a barrier every
  // iteration.
  TORCH_CHECK(sX_bytes + 2 * per_cout_bytes <= smem_budget,
              "input tile shared memory (", sX_bytes,
              " bytes) plus double-buffered single-output-channel weight slices (", 2 * per_cout_bytes,
              " bytes) exceeds the device shared-memory budget (", smem_budget,
              " bytes); reduce OH_TILE/OW_TILE");
  int COUT_TILE = (int)((smem_budget - sX_bytes) / (2 * per_cout_bytes));
  if (COUT_TILE < 1) COUT_TILE = 1;
  if (COUT_TILE > Cout) COUT_TILE = Cout;
  size_t smem_bytes = sX_bytes + 2 * (size_t)COUT_TILE * per_cout_bytes;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    auto attr_err = cudaFuncSetAttribute(conv2d_cute_kernel,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
    TORCH_CHECK(attr_err == cudaSuccess,
                "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));
  }
  conv2d_cute_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      N, Cin, H, Win,
      Cout, K, stride, padding,
      Hout, Wout,
      OH_TILE, OW_TILE, IH_TILE, IW_TILE, COUT_TILE
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
