class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        # Keep an nn.Conv2d only to hold/initialize the parameters identically
        # to the reference model; the actual computation is done by our
        # custom CUTE kernel in forward().
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        self._ext = conv2d_ext
        self.stride = 4
        self.padding = 2

    def forward(self, x):
        x = x.contiguous()
        weight = self.conv1.weight.contiguous()
        bias = self.conv1.bias
        return self._ext.conv2d_cute_forward(
            x, weight,
            bias if bias is not None else None,
            self.stride, self.padding,
        )

