#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void conv2d_cute_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ Bs,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Hout, int Wout,
    int OH_TILE, int OW_TILE, int IH_TILE, int IW_TILE)
{
  const int n  = blockIdx.z;
  const int th = blockIdx.y; // tile row idx
  const int tw = blockIdx.x; // tile col idx

  const int oh0 = th * OH_TILE;
  const int ow0 = tw * OW_TILE;
  const int ih0 = oh0 * stride - padding;
  const int iw0 = ow0 * stride - padding;

  extern __shared__ float smem[];

  // Shared-memory tensor: (Cin, IH_TILE, IW_TILE)
  auto sX = make_tensor(make_smem_ptr(smem),
                         make_shape(Cin, IH_TILE, IW_TILE),
                         make_stride(IH_TILE * IW_TILE, IW_TILE, 1));

  // Global input tensor for this batch element: (Cin, H, Win)
  int64_t sXn = (int64_t)Cin * H * Win;
  int64_t sXc = (int64_t)H * Win;
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                         make_shape(Cin, H, Win),
                         make_stride(sXc, (int64_t)Win, (int64_t)1));

  // Weight tensor: (Cout, Cin, K, K)
  auto mW = make_tensor(make_gmem_ptr(Wt),
                         make_shape(Cout, Cin, K, K),
                         make_stride((int64_t)Cin * K * K, (int64_t)K * K, (int64_t)K, (int64_t)1));

  // Global output tensor for this batch element: (Cout, Hout, Wout)
  int64_t sYn = (int64_t)Cout * Hout * Wout;
  int64_t sYc = (int64_t)Hout * Wout;
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                         make_shape(Cout, Hout, Wout),
                         make_stride(sYc, (int64_t)Wout, (int64_t)1));

  // Cooperative load of the input tile into shared memory (zero-padded).
  const int tid       = threadIdx.y * blockDim.x + threadIdx.x;
  const int nthreads   = blockDim.x * blockDim.y;
  const int total_elem = Cin * IH_TILE * IW_TILE;
  const int plane      = IH_TILE * IW_TILE;

  for (int idx = tid; idx < total_elem; idx += nthreads) {
    int c   = idx / plane;
    int rem = idx - c * plane;
    int ihl = rem / IW_TILE;
    int iwl = rem - ihl * IW_TILE;

    int ih = ih0 + ihl;
    int iw = iw0 + iwl;

    float v = 0.0f;
    if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
      v = mX(c, ih, iw);
    }
    sX(c, ihl, iwl) = v;
  }
  __syncthreads();

  const int sp  = threadIdx.x; // spatial position index within the tile
  const int cg  = threadIdx.y; // channel-group index
  const int ncg = blockDim.y;

  if (sp < OH_TILE * OW_TILE) {
    const int ohl = sp / OW_TILE;
    const int owl = sp % OW_TILE;
    const int oh  = oh0 + ohl;
    const int ow  = ow0 + owl;

    if (oh < Hout && ow < Wout) {
      const int COT = 4; // register-blocking factor: compute COT output channels per iteration,
                         // reusing each shared-memory input value across all of them.
      for (int co = cg; co < Cout; co += ncg * COT) {
        float acc[COT];
        #pragma unroll
        for (int t = 0; t < COT; ++t) {
          int cot = co + t * ncg;
          acc[t] = (cot < Cout && Bs != nullptr) ? Bs[cot] : 0.0f;
        }
        #pragma unroll
        for (int c = 0; c < Cin; ++c) {
          for (int kh = 0; kh < K; ++kh) {
            int ihl = ohl * stride + kh;
            for (int kw = 0; kw < K; ++kw) {
              int iwl = owl * stride + kw;
              float xv = sX(c, ihl, iwl);
              #pragma unroll
              for (int t = 0; t < COT; ++t) {
                int cot = co + t * ncg;
                if (cot < Cout) {
