      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      N, Cin, H, Win,
      Cout, K, stride, padding,
      Hout, Wout,
      OH_TILE, OW_TILE, IH_TILE, IW_TILE
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));

